package com.ecole.gestion_scolaire.teacherportal.entity;
import com.ecole.gestion_scolaire.student.entity.Student; import jakarta.persistence.*; import java.math.*; import java.time.*;
@Entity @Table(name="teacher_evaluation_grade") public class TeacherEvaluationGrade { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="evaluation_id") private TeacherEvaluation evaluation; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="student_id") private Student student; private BigDecimal score; private boolean absent; @Column(columnDefinition="text") private String comment; private OffsetDateTime updatedAt; @PrePersist @PreUpdate void upd(){updatedAt=OffsetDateTime.now();} public Long getId(){return id;} public TeacherEvaluation getEvaluation(){return evaluation;} public void setEvaluation(TeacherEvaluation v){evaluation=v;} public Student getStudent(){return student;} public void setStudent(Student v){student=v;} public BigDecimal getScore(){return score;} public void setScore(BigDecimal v){score=v;} public boolean isAbsent(){return absent;} public void setAbsent(boolean v){absent=v;} public String getComment(){return comment;} public void setComment(String v){comment=v;} }
